UPDATE TBL_COMPANY_MEMBER_R
SET company_member_status_cd = #{memberStatusCd}, company_member_leave_dt = #{leaveDt}
WHERE user_sq = #{userSq} AND company_sq = #{companySq} AND company_member_status_cd = 401

mapper.select:
SELECT c.company_sq, c.company_nm, c.company_ceo_nm, c.company_open_dt, a.address_sq, c.company_url, c.company_biz_num, c.company_is_recruiting_yn, c.company_greeting_txt, c.company_view_cnt, a.address, a.detail_address,
(SELECT COUNT(*) FROM TBL_COMPANY_APPLICATION_H WHERE company_sq = c.company_sq AND user_sq = #{userSq} AND company_application_status_cd = 501 AND company_application_is_deleted_yn = 'N') > 0 AS is_apply,
(SELECT COUNT(*) FROM TBL_COMPANY_MEMBER_R WHERE company_sq = c.company_sq AND user_sq = #{userSq} AND company_member_status_cd = 401 AND company_member_leave_dt IS NULL) > 0 AS is_member, p.project_sq, p.project_ttl, p.project_description_txt, p.project_start_dt, p.project_end_dt, p.project_preference_txt, p.project_candidate_cnt, p.project_is_deleted_yn FROM TBL_COMPANY_S c LEFT JOIN TBL_ADDRESS_S a ON a.address_sq = c.address_sq LEFT JOIN TBL_PROJECT_M p ON p.company_sq = c.company_sq AND p.project_is_deleted_yn = 'N' AND p.project_end_dt >= CURDATE() WHERE c.company_sq = #{companySq}
